import{_ as d,o,c as e,a3 as a}from"./chunks/framework.DotqndlA.js";const r="/ems_simulate/assets/copy-dialog-single.CbMBNX3Y.png",l="/ems_simulate/assets/copy-dialog-batch.BemgpN2A.png",i="/ems_simulate/assets/copy-result.CXtpREPP.png",g=JSON.parse('{"title":"设备复制","description":"","frontmatter":{},"headers":[],"relativePath":"guide/device/device-copy.md","filePath":"guide/device/device-copy.md","lastUpdated":1787009981000}'),c={name:"guide/device/device-copy.md"};function s(n,t,h,u,q,b){return o(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="设备复制" tabindex="-1">设备复制 <a class="header-anchor" href="#设备复制" aria-label="Permalink to &quot;设备复制&quot;">​</a></h1><h2 id="一、概述" tabindex="-1">一、概述 <a class="header-anchor" href="#一、概述" aria-label="Permalink to &quot;一、概述&quot;">​</a></h2><p><strong>设备复制</strong>用于快速复制已有设备（含整套测点配置），避免重复配置。支持<strong>单个复制</strong>与<strong>批量复制</strong>两种模式：</p><table tabindex="0"><thead><tr><th>模式</th><th>适用场景</th><th>特点</th></tr></thead><tbody><tr><td>单个复制</td><td>复制一台设备</td><td>可指定目标名称、编码、IP、端口</td></tr><tr><td>批量复制</td><td>一次复制多台设备</td><td>设置数量、前缀/后缀、起始 IP、各段偏移、端口偏移</td></tr></tbody></table><blockquote><p>复制内容：设备基本信息 + <strong>整套测点配置</strong>（含系数、解析码、上下限、品质等），IEC 61850 设备额外复制模型文件与 GOOSE/Reports/DataSet/订阅配置。</p></blockquote><h2 id="二、打开复制对话框" tabindex="-1">二、打开复制对话框 <a class="header-anchor" href="#二、打开复制对话框" aria-label="Permalink to &quot;二、打开复制对话框&quot;">​</a></h2><ol><li>在左侧<strong>设备树</strong>中选中要复制的设备；</li><li>点击设备操作菜单/按钮中的&quot;<strong>复制设备</strong>&quot;，弹出&quot;复制设备&quot;对话框；</li><li>对话框顶部提供两个页签：<strong>单个复制</strong>、<strong>批量复制</strong>。</li></ol><p><img src="'+r+'" alt=""></p><blockquote><p>复制设备对话框 - 单个复制页签（目标名称/编码/IP/端口）。</p></blockquote><h2 id="三、单个复制" tabindex="-1">三、单个复制 <a class="header-anchor" href="#三、单个复制" aria-label="Permalink to &quot;三、单个复制&quot;">​</a></h2><h3 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h3><ol><li>在&quot;复制设备&quot;对话框中选择&quot;<strong>单个复制</strong>&quot;页签；</li><li>填写目标设备信息：</li></ol><table tabindex="0"><thead><tr><th>配置项</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td>目标名称</td><td>新设备名称</td><td><code>电池模拟器-2</code></td></tr><tr><td>目标编码</td><td>新设备编码（全局唯一）</td><td><code>BAT_002</code></td></tr><tr><td>目标 IP</td><td>新设备 IP 地址（IPv4）</td><td><code>192.168.1.11</code></td></tr><tr><td>目标端口</td><td>新设备端口号</td><td><code>503</code></td></tr></tbody></table><ol start="3"><li>点击&quot;保存&quot;，系统复制源设备配置并创建新设备；</li><li>新设备出现在设备树中（可在&quot;设备管理&quot;中查看）。</li></ol><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><ul><li>目标编码必须<strong>全局唯一</strong>，否则提示&quot;设备编码已存在&quot;；</li><li>目标 IP 若与现有服务端冲突，会提示并阻止复制；</li><li>单个复制默认不自动启动设备，需要手动开启。</li></ul><h2 id="四、批量复制" tabindex="-1">四、批量复制 <a class="header-anchor" href="#四、批量复制" aria-label="Permalink to &quot;四、批量复制&quot;">​</a></h2><h3 id="操作步骤-1" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤-1" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h3><ol><li>在&quot;复制设备&quot;对话框中选择&quot;<strong>批量复制</strong>&quot;页签；</li><li>按下表配置：</li></ol><table tabindex="0"><thead><tr><th>配置项</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td>源设备</td><td>当前选中的设备（只读显示）</td><td>—</td></tr><tr><td>目标分组</td><td>新设备所属设备组（可选，默认跟随源设备）</td><td>储能区</td></tr><tr><td>前缀</td><td>新设备名称/编码前缀（可选）</td><td><code>DEV_</code></td></tr><tr><td>后缀</td><td>新设备名称/编码后缀（可选）</td><td><code>_COPY</code></td></tr><tr><td>复制数量</td><td>本次复制的设备台数</td><td><code>3</code></td></tr><tr><td>起始 IP</td><td>第一台设备的 IP</td><td><code>10.0.0.1</code></td></tr><tr><td>各段偏移</td><td>IP 地址 4 个段各自的偏移量</td><td><code>[0, 0, 1, 0]</code></td></tr><tr><td>端口偏移</td><td>端口随台数递增的偏移量（0 表示端口不变）</td><td><code>1</code></td></tr><tr><td>IEC 61850 完整复制</td><td>独立复制 ICD/SCD/CID 模型文件及 GOOSE/Reports/DataSet/订阅配置</td><td>勾选</td></tr></tbody></table><ol start="3"><li>查看下方&quot;<strong>复制预览</strong>&quot;：确认第 1 台、第 2 台设备的 IP 计算结果是否符合预期；</li><li>点击&quot;保存&quot;执行批量复制。</li></ol><p><img src="'+l+'" alt=""></p><blockquote><p>复制设备对话框 - 批量复制页签（数量/前缀后缀/起始IP/各段偏移/端口偏移/复制预览）。</p></blockquote><h3 id="ip-偏移规则" tabindex="-1">IP 偏移规则 <a class="header-anchor" href="#ip-偏移规则" aria-label="Permalink to &quot;IP 偏移规则&quot;">​</a></h3><p>第 n 台设备的第 k 段 IP = 起始 IP 第 k 段 + 偏移[k] × (n-1)，每段按 <strong>256 进制进位</strong>：</p><table tabindex="0"><thead><tr><th>起始 IP</th><th>各段偏移</th><th>数量</th><th>生成的 IP</th></tr></thead><tbody><tr><td><code>192.168.0.1</code></td><td><code>[0,0,0,1]</code></td><td>3</td><td><code>192.168.0.1</code> / <code>192.168.0.2</code> / <code>192.168.0.3</code></td></tr><tr><td><code>192.168.0.254</code></td><td><code>[0,0,0,2]</code></td><td>2</td><td><code>192.168.0.254</code> / <code>192.168.1.0</code>（末段溢出进位）</td></tr><tr><td><code>10.0.0.1</code></td><td><code>[0,0,1,0]</code></td><td>3</td><td><code>10.0.0.1</code> / <code>10.0.1.1</code> / <code>10.0.2.1</code></td></tr></tbody></table><blockquote><p>💡 偏移为 <code>0</code> 的段不随台数变化；第 1 段溢出视为超出 IPv4 范围会报错。</p></blockquote><h3 id="批量复制行为" tabindex="-1">批量复制行为 <a class="header-anchor" href="#批量复制行为" aria-label="Permalink to &quot;批量复制行为&quot;">​</a></h3><ul><li>新设备编码 = <code>前缀 + 源编码 + 后缀 + 台号</code>（如 <code>DEV_SRC_COPY1</code>、<code>DEV_SRC_COPY2</code>…）；</li><li>编码已存在或 IP:端口与现有服务端冲突时，<strong>自动跳过</strong>该台并提示，其余继续复制；</li><li>复制完成后提示&quot;成功复制 N 个设备&quot;。</li></ul><p><img src="'+i+'" alt=""></p><blockquote><p>批量复制完成后的设备列表（新增多台设备）与结果提示。</p></blockquote><h2 id="五、注意事项" tabindex="-1">五、注意事项 <a class="header-anchor" href="#五、注意事项" aria-label="Permalink to &quot;五、注意事项&quot;">​</a></h2><ul><li>复制数量上限为 256；</li><li>批量复制支持<strong>目标分组</strong>，可将新设备直接放入指定设备组；</li><li>IEC 61850 设备复制默认<strong>深拷贝模型文件</strong>，新设备不会指向源设备的模型文件；</li><li>复制后的设备默认<strong>停止</strong>状态，需手动开启（开启后自动应用测点模拟配置）。</li></ul>',33)])])}const P=d(c,[["render",s]]);export{g as __pageData,P as default};
